macro_rules! deps {
    () => {
        ConnectionNameType!();
        OutputType!();
        EmptyMutation!();
        Error!();
        Result!();
        ObjectType!();
        EmptySubscription!();
        Connection!();
        CursorType!();
        Object!();
        EmptyFields!();
        Query!();
        NodesFieldSwitcherSealed!();
        EdgeNameType!();
    };
}

